package cn.haiduo;
import java.util.*;import java.security.Principal;
import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;
import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.*;import org.springframework.transaction.support.TransactionTemplate;
import org.springframework.mock.web.MockHttpSession;import org.springframework.web.server.ResponseStatusException;
import org.testcontainers.postgresql.PostgreSQLContainer;import org.flywaydb.core.Flyway;
@org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable(named="RUN_DATABASE_TESTS",matches="true")
class ApprovalContainerTest {
 static PostgreSQLContainer pg;static JdbcTemplate db;static TransactionTemplate tx;UUID tenant,sku;MockHttpSession session;SkuApprovals api;
 @BeforeAll static void start(){pg=new PostgreSQLContainer("postgres:17.6").withDatabaseName("haiduo").withUsername("haiduo").withPassword("test-password");pg.start();var ds=new DriverManagerDataSource(pg.getJdbcUrl(),pg.getUsername(),pg.getPassword());Flyway.configure().dataSource(ds).load().migrate();db=new JdbcTemplate(ds);tx=new TransactionTemplate(new DataSourceTransactionManager(ds));}
 @AfterAll static void stop(){if(pg!=null)pg.stop();}
 @BeforeEach void setup(){tenant=UUID.randomUUID();sku=UUID.randomUUID();db.update("insert into tenant values(?,'approval')",tenant);db.update("insert into product(id,tenant_id,name) values(?,?,'original')",sku,tenant);db.update("insert into sku(id,tenant_id,code,name,cost,product_id) values(?,?,'A','original',200,?)",sku,tenant,sku);for(String u:List.of("trainee","supervisor","admin","finance")){db.update("insert into app_user(username,password_hash) values(?,'unused') on conflict do nothing",u);String role=u.equals("admin")?"ADMIN":u.equals("finance")?"FINANCE":"OPERATIONS";db.update("insert into membership values(?,?,?)",u,tenant,role);db.update("insert into member_grade values(?,?,?)",tenant,u,u.equals("trainee")?1:u.equals("admin")?4:3);}session=new MockHttpSession();session.setAttribute("activeTenant",tenant.toString());api=new SkuApprovals(db,new OperationsController(db,new SessionController(db),null));}
 Object submit(String name,String cost,String user){return tx.execute(s->api.submit(new SkuApprovals.Edit(sku,0,name,cost,"test reason"),()->user,session));}
 UUID id(Object result){return (UUID)((Map<?,?>)result).get("id");}
 void decide(UUID id,String action,String user){tx.execute(s->api.decide(id,new SkuApprovals.Decision(action,"reviewed"),()->user,session));}
 @Test void pendingThenApplyOnceAndRejectSelf(){UUID id=id(submit("changed","200","trainee"));assertEquals("original",db.queryForObject("select name from sku where id=?",String.class,sku));assertEquals(403,assertThrows(ResponseStatusException.class,()->decide(id,"approve","trainee")).getStatusCode().value());for(int i=0;i<10;i++)decide(id,"approve","supervisor");assertEquals("changed",db.queryForObject("select name from sku where id=?",String.class,sku));assertEquals(1,db.queryForObject("select version from sku where id=?",Integer.class,sku));assertEquals(1,db.queryForObject("select count(*) from outbox_event where tenant_id=? and kind='SKU_UPDATE'",Integer.class,tenant));}
 @Test void staleAndWithdrawNeverChangeSku(){UUID first=id(submit("one","200","trainee")),second=id(submit("two","200","trainee"));decide(first,"approve","supervisor");decide(second,"approve","supervisor");assertEquals("STALE",db.queryForObject("select status from sku_approval where id=?",String.class,second));}
 @Test void financialPermissionAndTenantIsolation(){assertThrows(ResponseStatusException.class,()->submit("cost","220","trainee"));UUID id=id(submit("cost","220","finance"));assertThrows(ResponseStatusException.class,()->decide(id,"approve","supervisor"));decide(id,"approve","admin");assertEquals("220.0000",db.queryForObject("select cost::text from sku where id=?",String.class,sku));UUID foreign=UUID.randomUUID();db.update("insert into tenant values(?,'other')",foreign);db.update("insert into membership values('admin',?,'ADMIN')",foreign);session.setAttribute("activeTenant",foreign.toString());assertEquals(404,assertThrows(ResponseStatusException.class,()->decide(id,"approve","admin")).getStatusCode().value());}
 @Test void rejectWithdrawAndExpiry(){UUID rejected=id(submit("reject","200","trainee"));decide(rejected,"reject","supervisor");UUID withdrawn=id(submit("withdraw","200","trainee"));decide(withdrawn,"withdraw","trainee");UUID expired=id(submit("expired","200","trainee"));db.update("update sku_approval set expires_at=now()-interval '1 second' where id=?",expired);decide(expired,"approve","supervisor");assertEquals("EXPIRED",db.queryForObject("select status from sku_approval where id=?",String.class,expired));assertEquals("original",db.queryForObject("select name from sku where id=?",String.class,sku));}
 @Test void requestAndConcurrentApprovalAreIdempotent(){UUID key=UUID.randomUUID();var edit=new SkuApprovals.Edit(sku,0,"repeat","200","same request",key);UUID id=null;for(int i=0;i<10;i++){UUID returned=id(tx.execute(s->api.submit(edit,()->"trainee",session)));if(id!=null)assertEquals(id,returned);id=returned;}assertEquals(1,db.queryForObject("select count(*) from sku_approval where tenant_id=?",Integer.class,tenant));UUID target=id;java.util.stream.IntStream.range(0,10).parallel().forEach(i->decide(target,"approve","supervisor"));assertEquals(1,db.queryForObject("select version from sku where id=?",Integer.class,sku));assertEquals(1,db.queryForObject("select count(*) from outbox_event where tenant_id=? and kind='SKU_UPDATE'",Integer.class,tenant));}
 @Test void revokedReviewerCannotApplyPendingRequest(){UUID id=id(submit("pending","200","trainee"));db.update("update member_grade set grade=2 where tenant_id=? and username='supervisor'",tenant);assertEquals(403,assertThrows(ResponseStatusException.class,()->decide(id,"approve","supervisor")).getStatusCode().value());assertEquals("PENDING",db.queryForObject("select status from sku_approval where id=?",String.class,id));assertEquals("original",db.queryForObject("select name from sku where id=?",String.class,sku));}
 @Test void revokedOrRemovedApplicantCanBeRejectedButNeverApproved(){UUID first=id(submit("revoked","200","trainee"));db.update("update membership set role='WAREHOUSE' where tenant_id=? and username='trainee'",tenant);assertEquals(403,assertThrows(ResponseStatusException.class,()->decide(first,"approve","supervisor")).getStatusCode().value());decide(first,"reject","supervisor");db.update("update membership set role='OPERATIONS' where tenant_id=? and username='trainee'",tenant);UUID second=id(submit("removed","200","trainee"));db.update("delete from member_grade where tenant_id=? and username='trainee'",tenant);db.update("delete from membership where tenant_id=? and username='trainee'",tenant);assertEquals(403,assertThrows(ResponseStatusException.class,()->decide(second,"approve","supervisor")).getStatusCode().value());decide(second,"reject","supervisor");assertEquals(400,assertThrows(ResponseStatusException.class,()->decide(second,null,"supervisor")).getStatusCode().value());assertEquals("original",db.queryForObject("select name from sku where id=?",String.class,sku));}
}
